// Generated by the evaluation tool. Safe to read, safe to delete.
//
// Wrap your model client once, where you construct it:
//
//   import { withEval } from './.eval/report.js';
//   const client = withEval(new Anthropic({ apiKey }));
//
// That is the whole change. Which prompt was sent is recognised from its own text, so there is no id
// to pass and nothing to keep in sync when a prompt moves or is renamed.
//
// It reports: a fingerprint of the prompt, the model, the decoding settings, and hashes of the input
// and output. It does NOT send your prompt text or your users' data unless you turn that on in the
// dashboard. If the reporting call fails it is swallowed — measurement must never break the product
// it is measuring.

const ENDPOINT = "http://localhost:3000";

/** Set this from your environment. Without it the reporter is inert. */
const KEY = typeof process !== 'undefined' ? process.env.EVAL_INGEST_KEY : undefined;

/** Prompt fingerprint -> the id the evaluation tool knows it by. */
const PROMPTS = {
  "97pff0": "server/src/lib/prompts/agent::AGENT_PERSONA",
  "1qd2ib": "server/src/lib/prompts/blog::BLOG_SYSTEM_PROMPT",
  "1qzuw09": "server/src/lib/prompts/captions::captionPrompt.prompt",
  "d5d2p": "server/src/lib/prompts/summarizer::SUMMARIZER_PROMPTS.condense",
  "jwlzwm": "server/src/lib/prompts/summarizer::SUMMARIZER_PROMPTS.expand",
  "x51zk5": "server/src/routes/translate::TRANSLATE_SYSTEM_PROMPT",
};

function fingerprint(text) {
  const normalised = String(text).replace(/\s+/g, ' ').trim().slice(0, 80).toLowerCase();
  let h = 2166136261;
  for (let i = 0; i < normalised.length; i++) {
    h ^= normalised.charCodeAt(i);
    h = Math.imul(h, 16777619);
  }
  return (h >>> 0).toString(36);
}

/** The system prompt, wherever this SDK puts it. */
function systemOf(args) {
  if (!args || typeof args !== 'object') return '';
  if (typeof args.system === 'string') return args.system;
  if (Array.isArray(args.system)) return args.system.map((b) => (b && b.text) || '').join('');
  if (Array.isArray(args.messages)) {
    const first = args.messages.find((m) => m && m.role === 'system');
    if (first) return typeof first.content === 'string' ? first.content : '';
  }
  return '';
}

function textOf(response) {
  if (!response) return '';
  if (typeof response === 'string') return response;
  if (Array.isArray(response.content)) return response.content.map((b) => (b && b.text) || '').join('');
  if (response.choices && response.choices[0] && response.choices[0].message) {
    return String(response.choices[0].message.content || '');
  }
  return '';
}

function report(body) {
  if (!KEY) return;
  try {
    fetch(ENDPOINT + '/api/probe/generation', {
      method: 'POST',
      headers: { 'Content-Type': 'application/json', Authorization: 'Bearer ' + KEY },
      body: JSON.stringify(body),
      keepalive: true,
    }).catch(function () {});
  } catch (e) {
    /* Swallowed on purpose: this runs inside a request path that is not ours to fail. */
  }
}

/**
 * Wrap a model client so every call reports itself.
 *
 * Returns a Proxy, so nothing about the client's own behaviour changes — same methods, same types,
 * same errors. A call whose prompt we do not recognise is simply not reported.
 */
export function withEval(client) {
  if (!client || typeof client !== 'object') return client;
  return new Proxy(client, {
    get(target, prop, receiver) {
      const value = Reflect.get(target, prop, receiver);
      if (prop === 'messages' || prop === 'chat' || prop === 'completions' || prop === 'responses') {
        return withEval(value);
      }
      if (prop !== 'create' || typeof value !== 'function') return value;
      return function (args) {
        const started = Date.now();
        const rendered = systemOf(args);
        const uxid = PROMPTS[fingerprint(rendered)];
        const result = value.apply(target, arguments);
        if (!uxid || !result || typeof result.then !== 'function') return result;
        result
          .then(function (response) {
            report({
              uxid: uxid,
              renderedPrompt: rendered,
              modelId: (args && args.model) || 'unknown',
              decoding: {
                temperature: args && args.temperature,
                max_tokens: args && args.max_tokens,
              },
              output: textOf(response),
              latencyMs: Date.now() - started,
            });
          })
          .catch(function () {});
        return result;
      };
    },
  });
}
